"use client";

import AuthFrame from "@/components/auth/AuthFrame";
import PasswordField from "@/components/auth/PasswordField";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { useAuth } from "@/context/AuthContext";
import { AlertCircle, ArrowRight, CheckCircle2, ShieldCheck } from "lucide-react";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

type ApiResponse = {
  message?: string;
  user?: Parameters<ReturnType<typeof useAuth>["updateUser"]>[0];
  errors?: Record<string, string[]>;
};

function getApiMessage(data: ApiResponse, fallback: string) {
  return data.message || Object.values(data.errors ?? {})[0]?.[0] || fallback;
}

export default function ChangePassword() {
  const router = useRouter();
  const { user, token, isAuthReady, updateUser } = useAuth();
  const [formData, setFormData] = useState({
    current_password: "",
    password: "",
    password_confirmation: "",
  });
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  useEffect(() => {
    if (isAuthReady && !token) {
      router.replace("/login");
    }
  }, [isAuthReady, router, token]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage("");
    setSuccessMessage("");

    if (formData.password.length < 6) {
      setErrorMessage("Mật khẩu mới cần có ít nhất 6 ký tự.");
      return;
    }

    if (formData.password !== formData.password_confirmation) {
      setErrorMessage("Mật khẩu xác nhận không khớp.");
      return;
    }

    if (formData.current_password === formData.password) {
      setErrorMessage("Mật khẩu mới phải khác mật khẩu hiện tại.");
      return;
    }

    setIsLoading(true);

    try {
      const response = await fetch("/api/auth/change-password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify(formData),
      });

      const data: ApiResponse = await response.json();

      if (response.ok) {
        updateUser(data.user ?? { must_change_password: false });
        setSuccessMessage(data.message || "Đổi mật khẩu thành công.");
        router.push("/");
      } else {
        setErrorMessage(getApiMessage(data, "Chưa thể đổi mật khẩu."));
      }
    } catch {
      setErrorMessage("Lỗi kết nối đến máy chủ. Vui lòng thử lại sau.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthFrame
      mode="change-password"
      bannerBadge="Xác nhận bảo mật"
      bannerTitle="Đặt mật khẩu mới trước khi tiếp tục."
      bannerDescription="Tài khoản đang dùng mật khẩu tạm thời. Sau bước này bạn có thể mua sắm, theo dõi đơn hàng và lưu sản phẩm yêu thích như bình thường."
    >
      <Card className="flex w-full flex-col border-border bg-card shadow-md">
        <CardHeader className="space-y-3 pb-5">
          <div className="inline-flex w-fit items-center gap-2 rounded-md border border-primary/20 bg-primary/10 px-3 py-1 text-xs font-semibold text-primary">
            <ShieldCheck className="h-3.5 w-3.5" />
            {user?.must_change_password ? "Yêu cầu đổi mật khẩu" : "Bảo mật tài khoản"}
          </div>
          <div className="space-y-2">
            <CardTitle className="text-3xl font-bold text-foreground">
              Đổi mật khẩu
            </CardTitle>
            <CardDescription className="text-base leading-relaxed">
              Nhập mật khẩu hiện tại và đặt mật khẩu mới cho tài khoản BloomShop.
            </CardDescription>
          </div>
        </CardHeader>

        <CardContent className="flex-1">
          {errorMessage && (
            <div className="mb-5 flex items-start gap-3 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{errorMessage}</span>
            </div>
          )}

          {successMessage && (
            <div className="mb-5 flex items-start gap-3 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">
              <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{successMessage}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <label htmlFor="current_password" className="text-sm font-semibold text-foreground">
                Mật khẩu hiện tại
              </label>
              <PasswordField
                id="current_password"
                name="current_password"
                value={formData.current_password}
                placeholder="Nhập mật khẩu tạm thời"
                showPassword={showCurrentPassword}
                onTogglePassword={() => setShowCurrentPassword((prev) => !prev)}
                onChange={handleInputChange}
              />
            </div>

            <div className="space-y-2">
              <label htmlFor="password" className="text-sm font-semibold text-foreground">
                Mật khẩu mới
              </label>
              <PasswordField
                id="password"
                name="password"
                value={formData.password}
                placeholder="Tối thiểu 6 ký tự"
                showPassword={showPassword}
                onTogglePassword={() => setShowPassword((prev) => !prev)}
                onChange={handleInputChange}
              />
            </div>

            <div className="space-y-2">
              <label htmlFor="password_confirmation" className="text-sm font-semibold text-foreground">
                Xác nhận mật khẩu mới
              </label>
              <PasswordField
                id="password_confirmation"
                name="password_confirmation"
                value={formData.password_confirmation}
                placeholder="Nhập lại mật khẩu mới"
                showPassword={showConfirmPassword}
                onTogglePassword={() => setShowConfirmPassword((prev) => !prev)}
                onChange={handleInputChange}
              />
            </div>

            <Button
              type="submit"
              size="lg"
              disabled={isLoading || !token}
              className="h-11 w-full rounded-lg bg-primary text-primary-foreground shadow-md hover:bg-primary/90"
            >
              {isLoading ? (
                <>
                  <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
                  Đang đổi mật khẩu...
                </>
              ) : (
                <>
                  Lưu mật khẩu mới
                  <ArrowRight className="h-4 w-4" />
                </>
              )}
            </Button>
          </form>
        </CardContent>
      </Card>
    </AuthFrame>
  );
}
